function engraveProcess(data,w,h,opts){
  opts=opts||{};
  var density=opts.density!=null?opts.density:6;
  var angleDeg=opts.angle!=null?opts.angle:45;
  if(density<2)density=2; else if(density>20)density=20;
  if(angleDeg<0)angleDeg=0; else if(angleDeg>90)angleDeg=90;
  var a=angleDeg*Math.PI/180, ca=Math.cos(a), sa=Math.sin(a);
  var a2=(angleDeg+90)*Math.PI/180, ca2=Math.cos(a2), sa2=Math.sin(a2);
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var p=(y*w+x)*4;
    var L=0.299*data[p]+0.587*data[p+1]+0.114*data[p+2];
    var d=1-L/255;
    var period=Math.max(2, density + d*d*14);
    var ph=(((x*ca+y*sa)%period)+period)%period;
    var ink=(ph<1.0)?1:0;
    if(d>0.7){ var period2=Math.max(2, density+d*d*10); var ph2=(((x*ca2+y*sa2)%period2)+period2)%period2; if(ph2<1.0) ink=1; }
    var v=ink?0:248;
    out[p]=v; out[p+1]=v; out[p+2]=v; out[p+3]=data[p+3];
  }
  return out;
}

var EXPORTS={engraveProcess:engraveProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EngraveForgePure = EXPORTS; }
